class Solution {
public:
    string mostCommonWord(string paragraph, vector<string>& banned) {
        unordered_set<string> banned_set(banned.begin(), banned.end());
        unordered_map<string, int> counts;
        for (char& c : paragraph) {
            c = isalpha(c) ? tolower(c) : ' ';
        }
        stringstream ss(paragraph);
        string w;
        string best_word = "";
        int max_cnt = 0;
        while (ss >> w) {
            if (!banned_set.count(w)) {
                counts[w]++;
                if (counts[w] > max_cnt) {
                    max_cnt = counts[w];
                    best_word = w;
                }
            }
        }
        return best_word;
    }
};

class Solution {
    public String mostCommonWord(String paragraph, String[] banned) {
        Set<String> bannedSet = new HashSet<>(Arrays.asList(banned));
        String[] words = paragraph.toLowerCase().split("[^a-z]+");
        Map<String, Integer> counts = new HashMap<>();
        String best = "";
        int maxCnt = 0;
        for (String w : words) {
            if (!w.isEmpty() && !bannedSet.contains(w)) {
                int cnt = counts.getOrDefault(w, 0) + 1;
                counts.put(w, cnt);
                if (cnt > maxCnt) {
                    maxCnt = cnt;
                    best = w;
                }
            }
        }
        return best;
    }
}

var mostCommonWord = function(paragraph, banned) {
    const bannedSet = new Set(banned);
    const words = paragraph.toLowerCase().match(/[a-z]+/g) || [];
    const counts = new Map();
    let best = '';
    let maxCnt = 0;
    for (const w of words) {
        if (!bannedSet.has(w)) {
            const cnt = (counts.get(w) || 0) + 1;
            counts.set(w, cnt);
            if (cnt > maxCnt) {
                maxCnt = cnt;
                best = w;
            }
        }
    }
    return best;
};
